PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE guests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  invitation_code TEXT UNIQUE,

  full_name TEXT NOT NULL,
  phone TEXT,
  email TEXT,

  specialty TEXT,
  hospital TEXT,

  group_name TEXT,

  is_vip INTEGER NOT NULL DEFAULT 0,
  vip_level TEXT,

  rsvp_status TEXT NOT NULL DEFAULT 'pending',

  table_number INTEGER,
  seat_number INTEGER,

  qr_token TEXT UNIQUE,

  whatsapp_status TEXT DEFAULT 'pending',
  email_status TEXT DEFAULT 'pending',

  checked_in INTEGER NOT NULL DEFAULT 0,
  checked_in_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, group_id TEXT, table_locked INTEGER NOT NULL DEFAULT 0, governorate TEXT, invited_by TEXT, first_name TEXT, last_name TEXT);
CREATE TABLE admin_sessions (
  token TEXT PRIMARY KEY,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE event_tables (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  table_number INTEGER NOT NULL UNIQUE,

  capacity INTEGER NOT NULL DEFAULT 7,

  table_type TEXT NOT NULL DEFAULT 'regular'
    CHECK (table_type IN ('regular', 'vip')),

  is_active INTEGER NOT NULL DEFAULT 1,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_guests_phone
ON guests(phone);
CREATE INDEX idx_guests_email
ON guests(email);
CREATE INDEX idx_guests_rsvp
ON guests(rsvp_status);
CREATE INDEX idx_guests_table
ON guests(table_number);
CREATE INDEX idx_guests_vip
ON guests(is_vip);
CREATE INDEX idx_admin_sessions_expires
ON admin_sessions(expires_at);
CREATE UNIQUE INDEX idx_unique_table_seat
ON guests (
  table_number,
  seat_number
)
WHERE
  table_number IS NOT NULL
  AND seat_number IS NOT NULL;
CREATE INDEX idx_guests_group_id
ON guests(group_id);
CREATE INDEX idx_guests_table_locked
ON guests(table_locked);
CREATE INDEX idx_event_tables_type
ON event_tables(table_type);
CREATE UNIQUE INDEX idx_guests_unique_table_seat
ON guests (table_number, seat_number)
WHERE table_number IS NOT NULL
  AND seat_number IS NOT NULL;
